package io.lumine.mythic.lib.player.particle.type;
import io.lumine.mythic.lib.player.particle.*;import io.lumine.mythic.lib.util.configobject.ConfigObject;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.Vec3d;import java.util.Map;
public class VortexParticleEffect extends ParticleEffect{private final double speed,height,radius,rSpeed,ySpeed;private final int amount;private double j;public VortexParticleEffect(String k,Map<String,Double>m,ParticleInformation p){super(k,p);speed=resolveModifier(m,"speed");height=resolveModifier(m,"height");radius=resolveModifier(m,"radius");ySpeed=resolveModifier(m,"y-speed");rSpeed=resolveModifier(m,"rotation-speed");amount=(int)resolveModifier(m,"amount");}public VortexParticleEffect(ConfigObject o){super(o);speed=o.getDouble("speed");height=o.getDouble("height");radius=o.getDouble("radius");ySpeed=o.getDouble("y-speed");rSpeed=o.getDouble("rotation-speed");amount=o.getInt("amount");}public ParticleEffectType getType(){return ParticleEffectType.VORTEX;}public void tick(){ServerPlayerEntity pl=playerData.getPlayer();Vec3d b=pl.getPos();double r=j/Math.PI/2;int n=Math.max(1,amount);for(int k=0;k<n;k++){double a=j+Math.PI*2*k/n;particle.display(pl.getServerWorld(),b.add(Math.cos(a)*radius*(1-r*ySpeed),r*ySpeed*height,Math.sin(a)*radius*(1-r*ySpeed)),speed);}j+=Math.PI/24*rSpeed;if(ySpeed!=0&&j>Math.PI*2/ySpeed)j-=Math.PI*2/ySpeed;}}
